static char __cccc_stdstring_h[1947] = "/* string.h - string manipulation functions for CCCC C compiler */\n\n#ifndef __STRING_H\n#define __STRING_H\n\nextern void *memcpy(void *dest, const void *src, long n);\nextern void *memmove(void *dest, const void *src, long n);\nextern void *memset(void *s, int c, long n);\nextern int memcmp(const void *s1, const void *s2, long n);\nextern void *memchr(const void *s, int c, long n);\n\nextern long strlen(const char *s);\nextern char *strcpy(char *dest, const char *src);\nextern char *strncpy(char *dest, const char *src, long n);\nextern char *strcat(char *dest, const char *src);\nextern char *strncat(char *dest, const char *src, long n);\nextern int strcmp(const char *s1, const char *s2);\nextern int strncmp(const char *s1, const char *s2, long n);\nextern char *strchr(const char *s, int c);\nextern char *strrchr(const char *s, int c);\nextern char *strstr(const char *haystack, const char *needle);\nextern long strxfrm(char *dest, const char *src, long n);\nextern char* strerror(int errnum);\n\n// extern char* strcpy_s(char *dest, long destsz, const char *src);\n// extern char* strncpy_s(char *dest, long destsz, const char *src, long n);\n// extern char* strcat_s(char *dest, long destsz, const char *src);\n// extern char* strncat_s(char *dest, long destsz, const char *src, long n);\nextern char* strdup(const char *s);\nextern char* strndup(const char *s, long n);\n// extern long strnlen_s(const char *s, long maxsize);\n// extern char* strtok_s(char *str, const char *delim, char **context);\nextern void* memset_explicit(void *s, int c, long n);\n// extern int memset_s(void *s, long smax, int c, long n);\n// extern void* memcpy_s(void *dest, long destsz, const void *src, long n);\n// extern void* memmove_s(void *dest, long destsz, const void *src, long n);\nextern void* memccpy(void *dest, const void *src, int c, long n);\n// extern int strerror_s(char *buf, long bufsz, int errnum);\n// extern long strerrorlen_s(int errnum);\n\n#endif /* __STRING_H */\n";
static char __cccc_stdstrings_h[597] = "/* strings.h - POSIX string functions supplement for CCCC */\n\n#ifndef __STRINGS_H\n#define __STRINGS_H\n\n#ifdef _WIN32\n#error \"<strings.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"stddef.h\"\n\nextern int strcasecmp(const char *s1, const char *s2);\nextern int strncasecmp(const char *s1, const char *s2, size_t n);\nextern void bzero(void *s, size_t n);\nextern void bcopy(const void *src, void *dst, size_t n);\nextern int bcmp(const void *s1, const void *s2, size_t n);\nextern char *index(const char *s, int c);\nextern char *rindex(const char *s, int c);\n\n#endif /* __STRINGS_H */\n";
static char __cccc_stdsys_cdefs_h[761] = "/*\n * CCCC wrapper for sys/cdefs.h\n * \n * This stub includes Availability.h first (to set up CCCC compatibility macros)\n * then includes the real sys/cdefs.h from the system include path.\n * \n * The order matters because sys/cdefs.h uses __GNUC__ and __has_attribute\n * to define macros that CCCC cannot parse (like __attribute__((__always_inline__))).\n * By including Availability.h first, we ensure __has_attribute returns 0\n * and __attribute__ is stripped.\n */\n\n#ifndef _CCCC_SYS_CDEFS_H_\n#define _CCCC_SYS_CDEFS_H_\n\n/* Include CCCC's Availability.h stub first to set up compatibility macros */\n#include <Availability.h>\n\n/* Now include the real sys/cdefs.h - but we need to use include_next */\n#include_next <sys/cdefs.h>\n\n#endif /* _CCCC_SYS_CDEFS_H_ */\n";
static char __cccc_stdsys_mman_h[1182] = "/* sys/mman.h - memory management declarations for CCCC */\n\n#ifndef __SYS_MMAN_H\n#define __SYS_MMAN_H\n\n#ifdef _WIN32\n#error \"<sys/mman.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"unistd.h\"\n\n#define PROT_NONE  0x00\n#define PROT_READ  0x01\n#define PROT_WRITE 0x02\n#define PROT_EXEC  0x04\n\n#ifdef __APPLE__\n#define MAP_SHARED    0x0001\n#define MAP_PRIVATE   0x0002\n#define MAP_FIXED     0x0010\n#define MAP_ANON      0x1000\n#define MAP_ANONYMOUS MAP_ANON\n#else\n#define MAP_SHARED    0x01\n#define MAP_PRIVATE   0x02\n#define MAP_FIXED     0x10\n#define MAP_ANONYMOUS 0x20\n#define MAP_ANON      MAP_ANONYMOUS\n#endif\n\n#define MS_ASYNC      0x0001\n#define MS_SYNC       0x0002\n#define MS_INVALIDATE 0x0004\n\n#define MADV_NORMAL     0\n#define MADV_RANDOM     1\n#define MADV_SEQUENTIAL 2\n#define MADV_WILLNEED   3\n#define MADV_DONTNEED   4\n\nextern void *mmap(void *addr, size_t length, int prot, int flags, int fd, off_t offset);\nextern int munmap(void *addr, size_t length);\nextern int mprotect(void *addr, size_t len, int prot);\nextern int msync(void *addr, size_t len, int flags);\nextern int posix_madvise(void *addr, size_t len, int advice);\n\n#endif /* __SYS_MMAN_H */\n";
static char __cccc_stdsys_socket_h[1311] = "/* sys/socket.h - socket declarations for CCCC */\n\n#ifndef __SYS_SOCKET_H\n#define __SYS_SOCKET_H\n\n#ifdef _WIN32\n#error \"<sys/socket.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/types.h\"\n\n#ifdef __APPLE__\nstruct sockaddr {\n    unsigned char sa_len;\n    sa_family_t sa_family;\n    char sa_data[14];\n};\n#else\nstruct sockaddr {\n    sa_family_t sa_family;\n    char sa_data[14];\n};\n#endif\n\n#define SOCK_STREAM 1\n#define SOCK_DGRAM  2\n#define SOCK_RAW    3\n\n#ifdef __APPLE__\n#define SOL_SOCKET   0xffff\n#define SO_REUSEADDR 0x0004\n#else\n#define SOL_SOCKET   1\n#define SO_REUSEADDR 2\n#endif\n\n#define SHUT_RD   0\n#define SHUT_WR   1\n#define SHUT_RDWR 2\n\nextern int socket(int domain, int type, int protocol);\nextern int bind(int socket, const struct sockaddr *address, socklen_t address_len);\nextern int listen(int socket, int backlog);\nextern int accept(int socket, struct sockaddr *address, socklen_t *address_len);\nextern int connect(int socket, const struct sockaddr *address, socklen_t address_len);\nextern int setsockopt(int socket, int level, int option_name,\n                      const void *option_value, socklen_t option_len);\nextern int getsockname(int socket, struct sockaddr *address, socklen_t *address_len);\nextern int shutdown(int socket, int how);\n\n#endif /* __SYS_SOCKET_H */\n";
static char __cccc_stdsys_stat_h[2476] = "/* sys/stat.h - file status for CCCC */\n\n#ifndef __SYS_STAT_H\n#define __SYS_STAT_H\n\n#ifdef _WIN32\n#error \"<sys/stat.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"sys/types.h\"\n\n/* Pull in struct timespec and time_t */\n#include \"../time.h\"\n\n#ifdef __APPLE__\n\nstruct stat {\n    dev_t     st_dev;\n    mode_t    st_mode;\n    nlink_t   st_nlink;\n    ino_t     st_ino;\n    uid_t     st_uid;\n    gid_t     st_gid;\n    dev_t     st_rdev;\n    struct timespec st_atimespec;\n    struct timespec st_mtimespec;\n    struct timespec st_ctimespec;\n    struct timespec st_birthtimespec;\n    off_t     st_size;\n    blkcnt_t  st_blocks;\n    blksize_t st_blksize;\n    unsigned int st_flags;\n    unsigned int st_gen;\n    int       st_lspare;\n    long long st_qspare[2];\n};\n\n#else\n/* Linux / generic POSIX */\n\nstruct stat {\n    unsigned long st_dev;\n    unsigned long st_ino;\n    unsigned long st_nlink;\n    unsigned int  st_mode;\n    unsigned int  st_uid;\n    unsigned int  st_gid;\n    unsigned int  __pad0;\n    unsigned long st_rdev;\n    long          st_size;\n    long          st_blksize;\n    long          st_blocks;\n    struct timespec st_atim;\n    struct timespec st_mtim;\n    struct timespec st_ctim;\n    long          __unused[3];\n};\n\n#endif\n\n#define S_IFMT   0xF000\n#define S_IFIFO  0x1000\n#define S_IFCHR  0x2000\n#define S_IFDIR  0x4000\n#define S_IFBLK  0x6000\n#define S_IFREG  0x8000\n#define S_IFLNK  0xA000\n#define S_IFSOCK 0xC000\n\n#define S_ISFIFO(m) (((m) & S_IFMT) == S_IFIFO)\n#define S_ISCHR(m)  (((m) & S_IFMT) == S_IFCHR)\n#define S_ISDIR(m)  (((m) & S_IFMT) == S_IFDIR)\n#define S_ISBLK(m)  (((m) & S_IFMT) == S_IFBLK)\n#define S_ISREG(m)  (((m) & S_IFMT) == S_IFREG)\n#define S_ISLNK(m)  (((m) & S_IFMT) == S_IFLNK)\n#define S_ISSOCK(m) (((m) & S_IFMT) == S_IFSOCK)\n\n#define S_IRWXU  0700\n#define S_IRUSR  0400\n#define S_IWUSR  0200\n#define S_IXUSR  0100\n#define S_IRWXG  0070\n#define S_IRGRP  0040\n#define S_IWGRP  0020\n#define S_IXGRP  0010\n#define S_IRWXO  0007\n#define S_IROTH  0004\n#define S_IWOTH  0002\n#define S_IXOTH  0001\n\n#define S_ISUID  04000\n#define S_ISGID  02000\n#define S_ISVTX  01000\n\nextern int stat(const char *path, struct stat *buf);\nextern int fstat(int fd, struct stat *buf);\nextern int lstat(const char *path, struct stat *buf);\nextern int chmod(const char *path, mode_t mode);\nextern int mkdir(const char *path, mode_t mode);\nextern int mkfifo(const char *path, mode_t mode);\nextern mode_t umask(mode_t cmask);\n\n#endif /* __SYS_STAT_H */\n";
static char __cccc_stdsys_time_h[996] = "/* sys/time.h - time types for CCCC */\n\n#ifndef __SYS_TIME_H\n#define __SYS_TIME_H\n\n#ifdef _WIN32\n#error \"<sys/time.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"time.h\"\n\nstruct timeval {\n    long tv_sec;\n    long tv_usec;\n};\n\nstruct timezone {\n    int tz_minuteswest;\n    int tz_dsttime;\n};\n\nextern int gettimeofday(struct timeval *tv, struct timezone *tz);\nextern int settimeofday(const struct timeval *tv, const struct timezone *tz);\n\n#define timeradd(a, b, res) do { \\\n    (res)->tv_sec = (a)->tv_sec + (b)->tv_sec; \\\n    (res)->tv_usec = (a)->tv_usec + (b)->tv_usec; \\\n    if ((res)->tv_usec >= 1000000) { \\\n        (res)->tv_sec++; \\\n        (res)->tv_usec -= 1000000; \\\n    } \\\n} while (0)\n\n#define timersub(a, b, res) do { \\\n    (res)->tv_sec = (a)->tv_sec - (b)->tv_sec; \\\n    (res)->tv_usec = (a)->tv_usec - (b)->tv_usec; \\\n    if ((res)->tv_usec < 0) { \\\n        (res)->tv_sec--; \\\n        (res)->tv_usec += 1000000; \\\n    } \\\n} while (0)\n\n#endif /* __SYS_TIME_H */\n";
static char __cccc_stdsys_types_h[1178] = "/* sys/types.h - basic system types for CCCC */\n\n#ifndef __SYS_TYPES_H\n#define __SYS_TYPES_H\n\n#ifdef _WIN32\n#error \"<sys/types.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#ifdef __APPLE__\ntypedef int               dev_t;\ntypedef unsigned long long ino_t;\ntypedef unsigned short    mode_t;\ntypedef unsigned short    nlink_t;\ntypedef unsigned int      uid_t;\ntypedef unsigned int      gid_t;\ntypedef long long         off_t;\ntypedef int               pid_t;\ntypedef int               blksize_t;\ntypedef long long         blkcnt_t;\ntypedef unsigned int      useconds_t;\ntypedef unsigned char     sa_family_t;\ntypedef unsigned int      socklen_t;\n#else\n/* Linux / generic POSIX */\ntypedef unsigned long     dev_t;\ntypedef unsigned long     ino_t;\ntypedef unsigned int      mode_t;\ntypedef unsigned long     nlink_t;\ntypedef unsigned int      uid_t;\ntypedef unsigned int      gid_t;\ntypedef long              off_t;\ntypedef int               pid_t;\ntypedef long              blksize_t;\ntypedef long              blkcnt_t;\ntypedef unsigned int      useconds_t;\ntypedef unsigned short    sa_family_t;\ntypedef unsigned int      socklen_t;\n#endif\n\n#endif /* __SYS_TYPES_H */\n";
static char __cccc_stdsys_wait_h[755] = "/* sys/wait.h - process wait declarations for CCCC */\n\n#ifndef __SYS_WAIT_H\n#define __SYS_WAIT_H\n\n#ifdef _WIN32\n#error \"<sys/wait.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#include \"unistd.h\"\n\n#define WNOHANG    1\n#define WUNTRACED  2\n\n#define WIFEXITED(status)   (((status) & 0x7f) == 0)\n#define WEXITSTATUS(status) (((status) >> 8) & 0xff)\n#define WIFSIGNALED(status) ((((status) & 0x7f) > 0) && (((status) & 0x7f) < 0x7f))\n#define WTERMSIG(status)    ((status) & 0x7f)\n#define WIFSTOPPED(status)  (((status) & 0xff) == 0x7f)\n#define WSTOPSIG(status)    WEXITSTATUS(status)\n#define WCOREDUMP(status)   ((status) & 0x80)\n\nextern pid_t wait(int *status);\nextern pid_t waitpid(pid_t pid, int *status, int options);\n\n#endif /* __SYS_WAIT_H */\n";
static char __cccc_stdtermios_h[1507] = "/* termios.h - terminal I/O declarations for CCCC */\n\n#ifndef __TERMIOS_H\n#define __TERMIOS_H\n\n#ifdef _WIN32\n#error \"<termios.h> is only available on POSIX targets in CCCC\"\n#endif\n\n#ifdef __APPLE__\ntypedef unsigned long tcflag_t;\ntypedef unsigned char cc_t;\ntypedef unsigned long speed_t;\n#define NCCS 20\nstruct termios {\n    tcflag_t c_iflag;\n    tcflag_t c_oflag;\n    tcflag_t c_cflag;\n    tcflag_t c_lflag;\n    cc_t c_cc[NCCS];\n    speed_t c_ispeed;\n    speed_t c_ospeed;\n};\n#else\ntypedef unsigned int tcflag_t;\ntypedef unsigned char cc_t;\ntypedef unsigned int speed_t;\n#define NCCS 32\nstruct termios {\n    tcflag_t c_iflag;\n    tcflag_t c_oflag;\n    tcflag_t c_cflag;\n    tcflag_t c_lflag;\n    cc_t c_line;\n    cc_t c_cc[NCCS];\n    speed_t c_ispeed;\n    speed_t c_ospeed;\n};\n#endif\n\n#define TCSANOW   0\n#define TCSADRAIN 1\n#define TCSAFLUSH 2\n\n#define VEOF   0\n#define VEOL   1\n#define VERASE 3\n#define VINTR  8\n#define VMIN   16\n#define VTIME  17\n\n#define BRKINT  0x00000002\n#define ICRNL   0x00000100\n#define IXON    0x00000200\n#define OPOST   0x00000001\n#define CS8     0x00000300\n#define CREAD   0x00000800\n#define ECHO    0x00000008\n#define ICANON  0x00000100\n#define ISIG    0x00000080\n\n#define B0       0\n#define B9600    9600\n#define B19200   19200\n#define B38400   38400\n#define B115200  115200\n\nextern int tcgetattr(int fildes, struct termios *termios_p);\nextern int tcsetattr(int fildes, int optional_actions,\n                     const struct termios *termios_p);\n\n#endif /* __TERMIOS_H */\n";
static char __cccc_stdtests_h[11386] = "/*\n CCCC test framework header \xe2\x80\x94 injected automatically in --testing mode.\n Do not include this directly; use the --testing flag instead.\n All assertion macros use the $ prefix to match the reflection.h convention.\n*/\n\n#pragma once\n\n// ============================================================================\n// Underlying FFI-callable assertion functions\n// ============================================================================\n\nvoid __cccc_assert(int cond, const char *expr, const char *file, int line);\nvoid __cccc_assert_false(int cond, const char *expr, const char *file, int line);\nvoid __cccc_assert_fail(const char *file, int line);\nvoid __cccc_assert_fail_msg(const char *msg, const char *file, int line);\nvoid __cccc_assert_eq(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\nvoid __cccc_assert_neq(long long a, long long b, const char *as, const char *bs,\n                      const char *file, int line);\nvoid __cccc_assert_gt(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\nvoid __cccc_assert_lt(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\nvoid __cccc_assert_ge(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\nvoid __cccc_assert_le(long long a, long long b, const char *as, const char *bs,\n                     const char *file, int line);\nvoid __cccc_assert_within(long long delta, long long expected, long long actual,\n                         const char *ds, const char *es, const char *as,\n                         const char *file, int line);\nvoid __cccc_assert_null(const void *p, const char *ps,\n                       const char *file, int line);\nvoid __cccc_assert_not_null(const void *p, const char *ps,\n                           const char *file, int line);\nvoid __cccc_assert_streq(const char *a, const char *b,\n                        const char *as, const char *bs,\n                        const char *file, int line);\nvoid __cccc_assert_streq_len(const char *a, const char *b, long long len,\n                            const char *as, const char *bs,\n                            const char *file, int line);\nvoid __cccc_assert_mem_eq(const void *expected, const void *actual, long long len,\n                         const char *es, const char *as,\n                         const char *file, int line);\nvoid __cccc_assert_float_within(double delta, double expected, double actual,\n                               const char *ds, const char *es, const char *as,\n                               const char *file, int line);\nvoid __cccc_assert_double_within(double delta, double expected, double actual,\n                                const char *ds, const char *es, const char *as,\n                                const char *file, int line);\nvoid __cccc_assert_bits(long long mask, long long expected, long long actual,\n                       const char *ms, const char *es, const char *as,\n                       const char *file, int line);\nvoid __cccc_assert_bit_high(int bit, long long actual,\n                           const char *bs, const char *as,\n                           const char *file, int line);\nvoid __cccc_assert_bit_low(int bit, long long actual,\n                          const char *bs, const char *as,\n                          const char *file, int line);\nvoid __cccc_assert_eq_array(const void *expected, const void *actual,\n                           long long elem_size, long long count,\n                           const char *es, const char *as,\n                           const char *file, int line);\n\n// Message-appending variants\nvoid __cccc_assert_msg(int cond, const char *expr, const char *msg,\n                      const char *file, int line);\nvoid __cccc_assert_eq_msg(long long a, long long b,\n                         const char *as, const char *bs, const char *msg,\n                         const char *file, int line);\nvoid __cccc_assert_streq_msg(const char *a, const char *b,\n                            const char *as, const char *bs, const char *msg,\n                            const char *file, int line);\nvoid __cccc_assert_null_msg(const void *p, const char *ps, const char *msg,\n                           const char *file, int line);\nvoid __cccc_assert_not_null_msg(const void *p, const char *ps, const char *msg,\n                               const char *file, int line);\nvoid __cccc_assert_bits_msg(long long mask, long long expected, long long actual,\n                           const char *ms, const char *es, const char *as,\n                           const char *msg, const char *file, int line);\n\n// ============================================================================\n// Basic Validity Assertions\n// ============================================================================\n\n#define $assert(cond) \\\n    __cccc_assert(!!(cond), #cond, __FILE__, __LINE__)\n#define $assert_true(cond) \\\n    $assert(cond)\n#define $assert_false(cond) \\\n    __cccc_assert_false(!!(cond), #cond, __FILE__, __LINE__)\n#define $assert_fail() \\\n    __cccc_assert_fail(__FILE__, __LINE__)\n#define $assert_fail_msg(msg) \\\n    __cccc_assert_fail_msg(msg, __FILE__, __LINE__)\n\n// ============================================================================\n// Numerical Assertions: Integers\n// ============================================================================\n\n#define $assert_eq(a, b) \\\n    __cccc_assert_eq((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n#define $assert_neq(a, b) \\\n    __cccc_assert_neq((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n#define $assert_gt(a, b) \\\n    __cccc_assert_gt((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n#define $assert_lt(a, b) \\\n    __cccc_assert_lt((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n#define $assert_ge(a, b) \\\n    __cccc_assert_ge((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n#define $assert_le(a, b) \\\n    __cccc_assert_le((long long)(a), (long long)(b), #a, #b, __FILE__, __LINE__)\n#define $assert_within(delta, expected, actual) \\\n    __cccc_assert_within((long long)(delta), (long long)(expected), (long long)(actual), \\\n                        #delta, #expected, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Numerical Assertions: Bitwise\n// ============================================================================\n\n#define $assert_bits(mask, expected, actual) \\\n    __cccc_assert_bits((long long)(mask), (long long)(expected), (long long)(actual), \\\n                      #mask, #expected, #actual, __FILE__, __LINE__)\n#define $assert_bit_high(bit, actual) \\\n    __cccc_assert_bit_high((int)(bit), (long long)(actual), \\\n                          #bit, #actual, __FILE__, __LINE__)\n#define $assert_bit_low(bit, actual) \\\n    __cccc_assert_bit_low((int)(bit), (long long)(actual), \\\n                         #bit, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Numerical Assertions: Floats / Doubles\n// ============================================================================\n\n#define $assert_float_within(delta, expected, actual) \\\n    __cccc_assert_float_within((double)(delta), (double)(expected), (double)(actual), \\\n                              #delta, #expected, #actual, __FILE__, __LINE__)\n#define $assert_double_within(delta, expected, actual) \\\n    __cccc_assert_double_within((double)(delta), (double)(expected), (double)(actual), \\\n                               #delta, #expected, #actual, __FILE__, __LINE__)\n#define $assert_float_eq(expected, actual) \\\n    __cccc_assert_float_within(1e-6, (double)(expected), (double)(actual), \\\n                              #expected, #expected, #actual, __FILE__, __LINE__)\n#define $assert_double_eq(expected, actual) \\\n    __cccc_assert_double_within(1e-15, (double)(expected), (double)(actual), \\\n                               #expected, #expected, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Pointer Assertions\n// ============================================================================\n\n#define $assert_null(p) \\\n    __cccc_assert_null((const void *)(p), #p, __FILE__, __LINE__)\n#define $assert_not_null(p) \\\n    __cccc_assert_not_null((const void *)(p), #p, __FILE__, __LINE__)\n\n// ============================================================================\n// String Assertions\n// ============================================================================\n\n#define $assert_streq(a, b) \\\n    __cccc_assert_streq((a), (b), #a, #b, __FILE__, __LINE__)\n#define $assert_streq_len(a, b, len) \\\n    __cccc_assert_streq_len((a), (b), (long long)(len), #a, #b, __FILE__, __LINE__)\n\n// ============================================================================\n// Memory Assertions\n// ============================================================================\n\n#define $assert_mem_eq(expected, actual, len) \\\n    __cccc_assert_mem_eq((const void *)(expected), (const void *)(actual), \\\n                        (long long)(len), #expected, #actual, __FILE__, __LINE__)\n\n// ============================================================================\n// Array Assertions\n// ============================================================================\n\n#define $assert_eq_array(expected, actual, count) \\\n    __cccc_assert_eq_array((const void *)(expected), (const void *)(actual), \\\n                          (long long)sizeof((expected)[0]), (long long)(count), \\\n                          #expected, #actual, __FILE__, __LINE__)\n#define $assert_each_eq(expected, actual, count) \\\n    do { \\\n        long long _cccc_i_; \\\n        for (_cccc_i_ = 0; _cccc_i_ < (long long)(count); _cccc_i_++) \\\n            __cccc_assert_eq((long long)((expected)), \\\n                           (long long)(((const typeof((actual)[0])*)(actual))[_cccc_i_]), \\\n                           #expected, #actual \"[i]\", \\\n                           __FILE__, __LINE__); \\\n    } while (0)\n\n// ============================================================================\n// Message-appending variants (_msg suffix)\n// ============================================================================\n\n#define $assert_msg(cond, msg) \\\n    __cccc_assert_msg(!!(cond), #cond, msg, __FILE__, __LINE__)\n#define $assert_true_msg(cond, msg) \\\n    $assert_msg(cond, msg)\n#define $assert_false_msg(cond, msg) \\\n    __cccc_assert_msg(!(cond), #cond, msg, __FILE__, __LINE__)\n#define $assert_eq_msg(a, b, msg) \\\n    __cccc_assert_eq_msg((long long)(a), (long long)(b), #a, #b, msg, \\\n                        __FILE__, __LINE__)\n#define $assert_streq_msg(a, b, msg) \\\n    __cccc_assert_streq_msg((a), (b), #a, #b, msg, __FILE__, __LINE__)\n#define $assert_null_msg(p, msg) \\\n    __cccc_assert_null_msg((const void *)(p), #p, msg, __FILE__, __LINE__)\n#define $assert_not_null_msg(p, msg) \\\n    __cccc_assert_not_null_msg((const void *)(p), #p, msg, __FILE__, __LINE__)\n#define $assert_bits_msg(mask, expected, actual, msg) \\\n    __cccc_assert_bits_msg((long long)(mask), (long long)(expected), (long long)(actual), \\\n                          #mask, #expected, #actual, msg, __FILE__, __LINE__)\n";
static char __cccc_stdtgmath_h[1690] = "/* tgmath.h - type-generic math macros for CCCC */\n\n#ifndef __TGMATH_H\n#define __TGMATH_H\n\n#include \"math.h\"\n#include \"complex.h\"\n\n#define __cccc_tg_unary(x, fd, ff, fl) _Generic((x), \\\n    long double: fl, \\\n    float: ff, \\\n    default: fd)(x)\n\n#define __cccc_tg_binary(x, y, fd, ff, fl) _Generic(((x) + (y)), \\\n    long double: fl, \\\n    float: ff, \\\n    default: fd)(x, y)\n\n#define __cccc_tg_real_or_complex_abs(x) _Generic((x), \\\n    long double _Complex: cabsl(x), \\\n    double _Complex: cabs(x), \\\n    float _Complex: cabsf(x), \\\n    long double: fabsl(x), \\\n    float: fabsf(x), \\\n    default: fabs(x))\n\n#define acos(x) __cccc_tg_unary((x), acos, acosf, acosl)\n#define asin(x) __cccc_tg_unary((x), asin, asinf, asinl)\n#define atan(x) __cccc_tg_unary((x), atan, atanf, atanl)\n#define cos(x) __cccc_tg_unary((x), cos, cosf, cosl)\n#define sin(x) __cccc_tg_unary((x), sin, sinf, sinl)\n#define tan(x) __cccc_tg_unary((x), tan, tanf, tanl)\n#define exp(x) __cccc_tg_unary((x), exp, expf, expl)\n#define log(x) __cccc_tg_unary((x), log, logf, logl)\n#define sqrt(x) __cccc_tg_unary((x), sqrt, sqrtf, sqrtl)\n#define fabs(x) __cccc_tg_real_or_complex_abs((x))\n#define floor(x) __cccc_tg_unary((x), floor, floorf, floorl)\n#define ceil(x) __cccc_tg_unary((x), ceil, ceilf, ceill)\n#define trunc(x) __cccc_tg_unary((x), trunc, truncf, truncl)\n#define round(x) __cccc_tg_unary((x), round, roundf, roundl)\n#define pow(x, y) __cccc_tg_binary((x), (y), pow, powf, powl)\n#define fmod(x, y) __cccc_tg_binary((x), (y), fmod, fmodf, fmodl)\n#define atan2(x, y) __cccc_tg_binary((x), (y), atan2, atan2f, atan2l)\n#define hypot(x, y) __cccc_tg_binary((x), (y), hypot, hypotf, hypotl)\n\n#endif /* __TGMATH_H */\n";
